def normalize(ps):
    mr=min(r for r,c in ps); mc=min(c for r,c in ps)
    return tuple(sorted((r-mr,c-mc) for r,c in ps)), max(r for r,c in ps)-mr+1, max(c for r,c in ps)-mc+1
