def transforms(mask):
    outs=[]
    for ref in [False,True]:
      for k in range(4):
        p=[(r,(-c if ref else c)) for r,c in mask]
        for _ in range(k): p=[(c,-r) for r,c in p]
        norm,hh,ww=normalize(p)
        if norm not in [x[0] for x in outs]: outs.append((norm,hh,ww,(ref,k)))
