def union_hits(D,pts, val=0, allow_transform=False):
  norm,_,_=normalize(pts)
  vs=transforms(norm) if allow_transform else [(norm,*normalize(norm)[1:],None)]
  out=set(); locations=[]
  for m,hh,ww,*rest in vs:
    ori=rest[0] if rest else None
    for r in range(D.shape[0]-hh+1):
     for c in range(D.shape[1]-ww+1):
      cells={(r+dr,c+dc) for dr,dc in m}
      if all(D[x,y]==val for x,y in cells):
       out|=cells;locations.append((r,c,ori))
  return out,locations
